{"Name":"MSExchange Management","Enabled":true,"IncludeMessage":true,"EventIds":[1,6]}
{"Name":"Security","Enabled":true}
{"Name":"System","Enabled":true}

racadm set iDRAC.SysLog.SysLogEnable Enabled
racadm set iDRAC.SysLog.Server1 {{siem_ip}}
racadm set iDRAC.SysLog.Port {{syslog_port}}
racadm get iDRAC.SysLog

tmsh create ltm pool pool-zyberon members add { {{siem_ip}}:{{syslog_port}} } monitor tcp
tmsh create sys log-config destination remote-high-speed-log hsl-zyberon pool-name pool-zyberon protocol tcp
tmsh create sys log-config destination remote-syslog syslog-zyberon remote-high-speed-log hsl-zyberon format rfc5424
tmsh create sys log-config publisher pub-zyberon destinations add { syslog-zyberon }
tmsh create security log profile zyberon-afm network add { zyberon-afm { publisher pub-zyberon filter { log-acl-match-accept enabled log-acl-match-drop enabled log-acl-match-reject enabled } } }
tmsh save sys config

USE master;
CREATE SERVER AUDIT ZyberonAudit TO SECURITY_LOG WITH (QUEUE_DELAY = 1000, ON_FAILURE = CONTINUE);
CREATE SERVER AUDIT SPECIFICATION ZyberonServerSpec FOR SERVER AUDIT ZyberonAudit
  ADD (FAILED_LOGIN_GROUP), ADD (SUCCESSFUL_LOGIN_GROUP), ADD (SERVER_ROLE_MEMBER_CHANGE_GROUP),
  ADD (SERVER_PERMISSION_CHANGE_GROUP), ADD (DATABASE_PERMISSION_CHANGE_GROUP), ADD (SCHEMA_OBJECT_CHANGE_GROUP),
  ADD (AUDIT_CHANGE_GROUP), ADD (SERVER_PRINCIPAL_CHANGE_GROUP) WITH (STATE = ON);
ALTER SERVER AUDIT ZyberonAudit WITH (STATE = ON);

$tok = Get-Content .\{{source_id}}.token -Raw
powershell -NoProfile -ExecutionPolicy Bypass -File .\install-relay.ps1 -CollectorUrl https://{{siem_host}} -SrcId {{source_id}} -Token $tok -Port {{syslog_port}}
Remove-Item .\{{source_id}}.token

ALTER SYSTEM SET UNIFIED_AUDIT_SYSTEMLOG = 'LOCAL6.INFO' SCOPE=SPFILE;
-- policies (built-in): 
AUDIT POLICY ORA_LOGON_FAILURES;
AUDIT POLICY ORA_SECURECONFIG;
AUDIT POLICY ORA_ACCOUNT_MGMT;
AUDIT POLICY ORA_DATABASE_PARAMETER;
-- custom: logons by everyone, DML on sensitive schemas by non-application accounts
CREATE AUDIT POLICY SENTRA_LOGONS ACTIONS LOGON, LOGOFF;
AUDIT POLICY SENTRA_LOGONS;
CREATE AUDIT POLICY SENTRA_SENSITIVE_DML ACTIONS SELECT ON HR.EMPLOYEES, UPDATE ON HR.EMPLOYEES, DELETE ON HR.EMPLOYEES;
AUDIT POLICY SENTRA_SENSITIVE_DML EXCEPT APP_HR;
SHUTDOWN IMMEDIATE; STARTUP;

ALTER SYSTEM SET AUDIT_TRAIL = 'OS' SCOPE=SPFILE;
ALTER SYSTEM SET AUDIT_SYSLOG_LEVEL = 'LOCAL6.INFO' SCOPE=SPFILE;
ALTER SYSTEM SET AUDIT_SYS_OPERATIONS = TRUE SCOPE=SPFILE;
AUDIT SESSION; AUDIT USER; AUDIT ROLE; AUDIT SYSTEM GRANT; AUDIT GRANT ANY PRIVILEGE; AUDIT ALTER SYSTEM; AUDIT AUDIT SYSTEM;
SHUTDOWN IMMEDIATE; STARTUP;
